/**
 * Stand-in for the catalog database that the ERP/PIM sync writes into.
 *
 * Module-level state keeps the demo self-contained: `syncCatalogFromUpstream`
 * mutates it so a sync produces a visible change in pricing/inventory, which is
 * what makes the background refresh observable in the admin UI.
 */

const BASE_CATALOG = [
  { id: 1, name: 'Laptop', price: 999, stock: 12 },
  { id: 2, name: 'Phone', price: 699, stock: 40 },
  { id: 3, name: 'Tablet', price: 499, stock: 7 },
  { id: 4, name: 'Headphones', price: 199, stock: 0 },
  { id: 5, name: 'Watch', price: 299, stock: 23 },
]

let revision = 0
let syncedAt = null
let catalog = BASE_CATALOG.map((product) => ({ ...product }))

export async function getAllProducts() {
  // Simulate database delay
  await new Promise((resolve) => setTimeout(resolve, 100))

  return catalog.map((product) => ({
    ...product,
    available: product.stock > 0,
  }))
}

export async function getCatalogRevision() {
  return { revision, syncedAt }
}

/**
 * Pull the latest pricing, inventory and availability from the upstream
 * ERP/PIM and persist it.
 *
 * A real sync touches thousands of SKUs, so treat this as the slow write: it is
 * why the admin page must not block on a freshly recomputed catalog.
 */
export async function syncCatalogFromUpstream() {
  // Simulate the upstream round-trip plus the bulk write.
  await new Promise((resolve) => setTimeout(resolve, 150))

  revision += 1
  syncedAt = new Date().toISOString()
  catalog = BASE_CATALOG.map((product, index) => ({
    ...product,
    // Deterministic stand-in for upstream deltas.
    price: product.price + ((revision * (index + 1) * 7) % 25),
    stock: Math.max(0, product.stock - ((revision * (index + 2)) % 5)),
  }))

  return { revision, syncedAt, skuCount: catalog.length }
}

